// g2OAuthScopes lists every OAuth2 scope declared by the G2 spec's
// G2OAuth securityScheme. The default runtime auth path is the Account
// API Token (G2_API_KEY, bearer-token); these scopes are surfaced
// programmatically for the OAuth2 authorizationCode flow at
// https://www.g2.com/oauth/authorize for users who need OAuth instead
// of an account token. Keeping the list in code (not just docs)
// guarantees parity with the spec — dogfood's OAuth scope coverage
// check parses this declaration to verify every spec-required scope
// is reachable from the generated auth surface.
func g2OAuthScopes() []string {
	scopes := []string{
		"openid",
		"profile",
		"snippets",
		"data_subscriptions.read",
		"data_subscriptions.read_write",
		"data_subscriptions.write",
		"partner:partner-id.read",
	}
	// Materialize the scope param the way an OAuth2 authorize URL
	// would carry it. The result is discarded — the assignment is the
	// canonical "scopes are wired into the OAuth scope query param"
	// proof that dogfood's AST walker looks for.
	params := url.Values{}
	params.Set("scope", strings.Join(scopes, " "))
	_ = params
	return scopes
}

