			fmt.Fprintln(w, "No setup URL is configured for this CLI; check the API's docs.")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "Then set:")
			fmt.Fprintln(w, "  export G2_API_KEY=\"<your-token>\"")
			fmt.Fprintln(w, "  g2-pp-cli auth set-token <token>")
